  "implementation": "def solve(case):
    # Extract payload
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build edges with mutual reachability
    edges = []
    for u, v, d in distances:
        if u not in core_distance or v not in core_distance:
            raise ValueError('Node missing from core_distance')
        mutual = max(core_distance[u], core_distance[v], d)
        # Canonicalize undirected endpoints
        min_node = min(u, v)
        max_node = max(u, v)
        edges.append((mutual, min_node, max_node, u, v))

    # Sort by mutual reachability, then min_node, then max_node
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    size = {node: 1 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return False
        if size[rx] < size[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        size[rx] += size[ry]
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)
    for mutual, min_node, max_node, u, v in edges:
        if len(mst_edges) == n - 1:
            break
        if union(u, v):
            mst_edges.append([u, v, mutual])
            total_weight += mutual

    if len(mst_edges) != n - 1:
        raise ValueError('Disconnected graph: cannot form spanning tree')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
